#include <bits/stdc++.h>
using namespace std;
int main(){
    vector<pair<long long,long long>> queries;
    string cmd;
    while(cin>>cmd){
        if(cmd=="#") break;
        long long qnum, period;
        cin>>qnum>>period;
        queries.push_back({qnum, period});
    }
    long long K;
    cin>>K;
    priority_queue<tuple<long long,long long,long long>, vector<tuple<long long,long long,long long>>, greater<>> pq;
    for (auto& q : queries) pq.push({q.second, q.first, q.second});
    for (long long i=0;i<K;i++){
        auto [t, qnum, period] = pq.top(); pq.pop();
        cout << qnum << "\n";
        pq.push({t+period, qnum, period});
    }
}

